#!/usr/bin/env node
/**
 * Writes every `package.json` in the repo — and every dependency each one
 * declares — into a plain data file the server owns, so the Tech portal's
 * Package Updates console can compare the whole monorepo against the npm
 * registry.
 *
 * Why a generated file rather than reading the tree at runtime: the API ships
 * as a Docker image that copies only the manifests `pnpm install` needs (root,
 * server and eighteen workspaces). `packages/*`, the native app, the docs site
 * and six more surfaces are never in that image, so a runtime `readdir` would
 * quietly report on a THIRD of the repo and look complete doing it. The list
 * travels as data instead, exactly as `shipped-keys.ts` does for localization.
 *
 * The workspace's OWN `version` is deliberately not recorded. The pre-commit
 * hook bumps `app/mweb` and `app/mobile-app` on every single commit, so a
 * manifest that carried versions would be stale the moment it was written and
 * the `--check` gate below would fail on commits that changed no dependency at
 * all. Declared dependency RANGES are what this console is about, and those
 * only move when somebody moves them.
 *
 * Run `node scripts/generate-package-manifest.mjs` after adding or bumping a
 * dependency; `--check` fails instead of writing, which is what CI runs so a
 * stale manifest cannot ship.
 */
import { readdirSync, readFileSync, statSync, writeFileSync } from "node:fs";
import { dirname, join, relative, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const OUT = join(
  ROOT,
  "server/src/modules/platform/packageUpdates/package-manifest.ts",
);
const NAME = "generate-package-manifest";
const check = process.argv.includes("--check");

/** Trees that hold somebody else's `package.json`, or a build of ours. */
const SKIP_DIR = new Set([
  "node_modules",
  ".git",
  "dist",
  "build",
  ".astro",
  ".expo",
  "coverage",
  "android",
  "ios",
]);

/**
 * Vendored third-party sources. CLAUDE.md rule 36 exempts `open-wa-server`
 * from this repo's standards, and its dependency list is not ours to bump —
 * reporting on it would put fifty rows nobody can action at the top of the
 * table.
 */
const SKIP_PATH = ["portals/crm/open-wa-server"];

/** The dependency blocks a manifest can declare, in the order they render. */
const DEP_KINDS = [
  "dependencies",
  "devDependencies",
  "peerDependencies",
  "optionalDependencies",
];

/** Repo-relative, forward-slashed — the same shape a path takes in the UI. */
const repoPath = (full) => relative(ROOT, full).split("\\").join("/");

function* manifestFiles(dir) {
  let entries;
  try {
    entries = readdirSync(dir);
  } catch {
    return;
  }
  for (const entry of entries.sort((a, b) => a.localeCompare(b))) {
    if (SKIP_DIR.has(entry)) continue;
    const full = join(dir, entry);
    if (SKIP_PATH.includes(repoPath(full))) continue;
    let stat;
    try {
      stat = statSync(full);
    } catch {
      continue;
    }
    if (stat.isDirectory()) yield* manifestFiles(full);
    else if (entry === "package.json") yield full;
  }
}

/** One `package.json`, reduced to the name, the path and what it declares. */
function readManifest(full) {
  const path = repoPath(full);
  const json = JSON.parse(readFileSync(full, "utf8"));
  const dependencies = [];
  for (const kind of DEP_KINDS) {
    const block = json[kind];
    if (!block) continue;
    for (const depName of Object.keys(block).sort((a, b) => a.localeCompare(b))) {
      dependencies.push({ name: depName, range: String(block[depName]), kind });
    }
  }
  return {
    name: json.name ?? path,
    path,
    private: json.private === true,
    dependencies,
  };
}

const packages = [...manifestFiles(ROOT)]
  .map(readManifest)
  .sort((a, b) => a.path.localeCompare(b.path));

const depCount = packages.reduce((sum, p) => sum + p.dependencies.length, 0);

const rows = packages
  .map((pkg) => {
    const deps = pkg.dependencies
      .map(
        (dep) =>
          `      { name: ${JSON.stringify(dep.name)}, range: ${JSON.stringify(dep.range)}, kind: ${JSON.stringify(dep.kind)} },`,
      )
      .join("\n");
    return [
      "  {",
      `    name: ${JSON.stringify(pkg.name)},`,
      `    path: ${JSON.stringify(pkg.path)},`,
      `    private: ${pkg.private},`,
      deps ? `    dependencies: [\n${deps}\n    ],` : "    dependencies: [],",
      "  },",
    ].join("\n");
  })
  .join("\n");

const file = `/**
 * GENERATED by \`node scripts/generate-package-manifest.mjs\` — do not edit.
 *
 * Every \`package.json\` in the repo and the dependency ranges it declares, as
 * plain data. The Tech portal's Package Updates console reads this through
 * \`packageUpdatesService\`, which asks the npm registry what each of these is
 * published at today.
 *
 * It is a generated FILE rather than a directory walk because the API's Docker
 * image only ever copies the manifests \`pnpm install\` needs — two thirds of
 * the repo is not in it, and a walk would report on the rest as if it were
 * everything.
 */

/** The block of a \`package.json\` a dependency was declared in. */
export type ManifestDependencyKind =
${DEP_KINDS.map((kind) => `  | '${kind}'`).join("\n")};

export interface ManifestDependency {
  name: string;
  /** Exactly what the manifest declares — \`^1.2.3\`, \`workspace:*\`, \`git+…\`. */
  range: string;
  kind: ManifestDependencyKind;
}

export interface ManifestPackage {
  /** The manifest's \`name\`, or its repo path when it declares none. */
  name: string;
  /** Repo-relative, forward-slashed path to the \`package.json\`. */
  path: string;
  private: boolean;
  dependencies: ManifestDependency[];
}

export const PACKAGE_MANIFEST: ManifestPackage[] = [
${rows}
];
`;

if (check) {
  let current = "";
  try {
    current = readFileSync(OUT, "utf8");
  } catch {
    console.error(`${NAME}: ${OUT} is missing — run the script without --check`);
    process.exit(1);
  }
  if (current !== file) {
    console.error(
      `${NAME}: package-manifest.ts is out of date (${packages.length} manifest(s), ${depCount} dependency row(s) on disk).\n` +
        "Run `node scripts/generate-package-manifest.mjs` and commit the result.",
    );
    process.exit(1);
  }
  console.log(
    `${NAME}: package-manifest.ts matches the tree (${packages.length} manifests, ${depCount} dependencies)`,
  );
} else {
  writeFileSync(OUT, file, "utf8");
  console.log(
    `${NAME}: wrote ${packages.length} manifest(s) / ${depCount} dependency row(s) to ${OUT.slice(ROOT.length + 1)}`,
  );
}
